import {KANA,LESSONS,BY_ID,SOURCES} from './content.mjs';
import {STORAGE_KEY,freshState,startSession,answer,advance,stats,validateState,dateKey} from './engine.mjs';
import {createGoogleSync} from './google-sync.mjs';

const paths={cloud:'M6 18a5 5 0 1 1 1-10 6 6 0 0 1 11-1 5 5 0 1 1 1 11H6Zm6-6v8m-3-3 3 3 3-3',sprout:'M12 21v-9m0 3C3 16 2 7 3 4c7-1 10 5 9 11Zm0-4C11 4 18 2 22 4c1 6-4 10-10 7Z',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-7h6v7',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M4 20V10m8 10V4m8 16v-7',book:'M12 6C8 3 4 3 2 4v15c3-1 6-1 10 2 4-3 7-3 10-2V4c-2-1-6-1-10 2Zm0 0v15',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',speaker:'m11 4-6 5H2v6h3l6 5V4Zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',repeat:'m20 7-4-4m4 4H7a4 4 0 0 0-4 4m1 6 4 4m-4-4h13a4 4 0 0 0 4-4',fire:'M12 2c1 6-5 7-5 11 0 3 2 5 5 5s5-2 5-5c0-2-1-4-2-5 0 3-2 3-2 3s2-5-1-9ZM7 8c-4 3-5 6-3 10 3 7 14 6 16-1 1-4-2-8-4-10',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',leaf:'M20 3C8 1 1 8 5 16s17 6 15-13ZM5 20 16 9',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app');
let state=freshState(),storageWorks=true,view='home',audio=null,toastTimer,playingId=null,cloud;
try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)state=validateState(JSON.parse(saved));}catch(error){storageWorks=false;}
if(state.session)view='lesson';
function save(sync=true){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageWorks=true;}catch(error){storageWorks=false;toast('Не удалось сохранить прогресс. Выгрузи его на вкладке «Прогресс».',true);}if(sync)cloud?.noteChange();}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`toast visible ${error?'error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5500);}
function navLink(id,label,i){return `<button class="nav-item ${view===id?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${view===id?'<span class="nav-dot"></span>':''}</button>`;}
function shell(body){const s=stats(state);return `<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="nav" data-view="home" aria-label="Кана — уроки"><span class="brand-mark" lang="ja">あ</span><span>Кана</span></button><nav aria-label="Основная навигация">${navLink('home','Уроки','home')}${navLink('alphabet','Азбука','grid')}${navLink('progress','Прогресс','chart')}${navLink('sync','Google Sheets','cloud')}</nav><div class="sidebar-bottom">${navLink('sources','Источники','book')}<div class="save-label"><span class="status-dot ${storageWorks?'':'warn'}"></span>${storageWorks?'Прогресс сохранён':'Сохранение недоступно'}</div></div></aside><div class="main-wrap"><header class="topbar"><span class="breadcrumb">Японский <span>／</span> <strong>Хирагана</strong></span><span class="mobile-brand" lang="ja">あ <span lang="ru">Кана</span></span><div class="top-stats"><span class="streak" title="Дни занятий подряд">${icon('fire')} ${s.streak}</span><span class="xp-pill">${icon('star')} ${state.xp} XP</span>${cloudIndicator()}</div></header><main id="main" tabindex="-1">${body}</main></div><nav class="mobile-nav" aria-label="Навигация на телефоне">${navLink('home','Уроки','home')}${navLink('alphabet','Азбука','grid')}${navLink('progress','Прогресс','chart')}</nav></div>`;}
function lessonCard(l,i){const completed=state.completed.includes(l.id);const next=!completed&&LESSONS.slice(0,i).every(x=>state.completed.includes(x.id));return `<button class="lesson-card ${next?'next':''} ${completed?'complete':''}" data-action="start" data-id="${l.id}"><span class="lesson-symbol" lang="ja">${completed?icon('check'):BY_ID[l.ids[0]].char}</span><span class="lesson-card-copy"><span class="lesson-kicker">УРОК ${String(i+1).padStart(2,'0')} <span>· ${l.ids.length} ЗНАК${l.ids.length===3?'А':'ОВ'}</span></span><strong>${l.label}</strong><span class="kana-preview" lang="ja">${l.ids.map(id=>BY_ID[id].char).join('　')}</span></span><span class="lesson-end">${next?'<span class="next-label">СЛЕДУЮЩИЙ</span>':completed?'<span class="done-label">Пройдено</span>':`<span class="lesson-time">${icon('clock')} ${l.duration} мин</span>`}<span class="lesson-arrow">${icon(next?'arrow':'chevron')}</span></span></button>`;}
function home(){
 const s=stats(state),active=state.session&&!state.session.finished;
 const next=active?LESSONS.find(l=>l.id===state.session.lessonId):LESSONS.find(l=>!state.completed.includes(l.id))||LESSONS[0];
 const nextTitle=active?(next?.label||(state.session.lessonId==='mistakes'?'Ошибки':'Повторение')):next.label;
 const step=active?(state.session.phase==='learn'?`Знак ${state.session.learnIndex+1} / ${state.session.ids.length}`:`Задание ${state.session.index+1} / ${state.session.questions.length}`):`${next.ids.length} знаков · ${next.duration} мин`;
 return shell(`<div class="page-heading compact-heading"><div><h1>Хирагана</h1><p>46 базовых знаков · 10 уроков</p></div></div><section class="study-summary" aria-label="Прогресс хираганы"><div><strong>${state.completed.length}<small> / 10</small></strong><span>уроков пройдено</span></div><div><strong>${s.mastered}<small> / 46</small></strong><span>знаков закреплено</span></div><div><strong>${s.accuracy}<small>%</small></strong><span>верных ответов</span></div></section><section class="continue-panel"><div class="continue-copy"><span class="eyebrow">${active?'ТЕКУЩИЙ УРОК':'СЛЕДУЮЩИЙ УРОК'}</span><h2>${nextTitle}</h2><span class="muted">${step}</span></div><button class="primary" data-action="${active?'resume':'start'}" data-id="${next?.id||'review'}">${active?'Продолжить':'Начать'}${icon('arrow')}</button></section><div class="review-actions"><button class="secondary" data-action="start" data-id="mistakes" ${!state.mistakes.length?'disabled':''}>${icon('repeat')} Ошибки <span class="count">${state.mistakes.length}</span></button><button class="secondary" data-action="start" data-id="review" ${!s.due?'disabled':''}>${icon('clock')} Повторение <span class="count">${s.due}</span></button></div><section class="lessons-section compact-lessons"><div class="section-heading"><h2>Уроки</h2><span class="muted">3–4 минуты каждый</span></div><div class="module-progress" role="progressbar" aria-label="Пройденные уроки" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${state.completed.length}"><span style="width:${state.completed.length*10}%"></span></div><div class="lesson-list">${LESSONS.map(lessonCard).join('')}</div></section>`);
}
function alphabet(){return shell(`<div class="page-heading"><div><h1>Азбука</h1><p>Нажми на знак, чтобы услышать его и увидеть подсказку.</p></div><span class="course-badge">46 базовых знаков</span></div><div class="alphabet-layout"><section class="surface alphabet-surface"><div class="alphabet-head"><h2>Хирагана · ひらがな</h2><span>а　и　у　э　о</span></div><div class="kana-table">${LESSONS.map(l=>`<div class="kana-table-row"><span class="row-label">${l.label}</span><div class="kana-row">${l.ids.map(id=>{const k=BY_ID[id],m=state.mastery[id];return `<button data-action="kana" data-id="${id}" class="kana-tile ${(m?.streak||0)>=3?'mastered':m?'seen':''}" aria-label="${k.char}, ${k.ru}, послушать"><span lang="ja">${k.char}</span><small>${id}</small><i></i></button>`;}).join('')}</div></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>Не изучен</span><span><i class="dot seen"></i>Знакомый знак</span><span><i class="dot mastered"></i>Закреплён</span></div></section><aside class="alphabet-note surface"><span class="big-serif" lang="ja">あ</span><h3>Один знак — одна мора</h3><p>Хирагана записывает звуковые единицы японского языка. Обычно знак соответствует гласному или сочетанию согласного с гласным.</p><p>Русская подсказка передаёт звук приблизительно. За образец бери запись.</p><div class="note-divider"></div><h3>Почему знаки иногда разные?</h3><p>Печатные и рукописные き и さ могут выглядеть немного по-разному. Чтение при этом сохраняется.</p><p class="tiny-note">Звонкие согласные, маленькая っ и сочетания вроде きゃ — следующий этап после базовых знаков.</p></aside></div>`);}
function progress(){const s=stats(state);const badges=[{icon:'sprout',title:'Первый урок',text:'Пройти первый урок',done:state.completed.length>0},{icon:'fire',title:'3 дня подряд',text:'Заниматься 3 дня подряд',done:s.streak>=3},{icon:'star',title:'100 XP',text:'Получить 100 XP',done:state.xp>=100},{icon:'book',title:'10 уроков',text:'Пройти все 10 уроков',done:state.completed.length===10}];return shell(`<div class="page-heading"><div><h1>Прогресс</h1><p>Результаты, ошибки и сохранение.</p></div><span class="course-badge">Уровень ${s.level}</span></div><div class="stat-grid"><div class="surface stat-card">${icon('star')}<strong>${state.xp}<small> XP</small></strong><span>опыта накоплено</span></div><div class="surface stat-card">${icon('grid')}<strong>${s.seen}<small> / 46</small></strong><span>знаков встречено</span></div><div class="surface stat-card">${icon('check')}<strong>${s.accuracy}<small>%</small></strong><span>верных ответов за всё время</span></div><div class="surface stat-card">${icon('fire')}<strong>${s.streak}</strong><span>дней подряд</span></div></div><section class="surface progress-panel"><div class="section-heading"><h2>Достижения</h2><span class="muted">${badges.filter(b=>b.done).length} / 4</span></div><div class="badges">${badges.map(b=>`<div class="badge-card ${b.done?'earned':''}"><span>${icon(b.icon)}</span><strong>${b.title}</strong><small>${b.text}</small></div>`).join('')}</div></section><div class="progress-columns"><section class="surface progress-panel"><h2>Ошибки</h2>${state.mistakes.length?`<div class="mistake-chips">${state.mistakes.map(id=>`<button data-action="kana" data-id="${id}" lang="ja">${BY_ID[id].char}<small>${id}</small></button>`).join('')}</div><button class="primary" data-action="start" data-id="mistakes">Повторить ошибки ${icon('repeat')}</button>`:'<p class="muted">Нет ошибок для повторения.</p>'}</section><section class="surface progress-panel"><h2>Сохранение</h2><p>Занятия сохраняются в этом браузере на этом устройстве. Чтобы перенести их на другой телефон, выгрузи файл и загрузи его там.</p><div class="backup-buttons"><button class="secondary" data-action="export">${icon('download')} Сохранить файл</button><button class="text-button" data-action="import">${icon('upload')} Загрузить прогресс</button></div><p class="tiny-note">Очистка данных браузера удалит местное сохранение. Файл поможет его восстановить.</p><button class="danger-link" data-action="reset">Начать заново</button></section></div><section class="surface progress-panel"><h2>Последние занятия</h2>${state.history.length?`<div class="history-list">${state.history.slice(0,6).map(h=>`<div><span>${esc(LESSONS.find(l=>l.id===h.lessonId)?.label||(h.lessonId==='mistakes'?'Повторение ошибок':'Повторение'))}</span><span class="muted">${esc(h.date.split('-').reverse().join('.'))} · ${h.correct}/${h.total} с первой попытки</span></div>`).join('')}</div>`:'<p class="muted">Завершённых занятий пока нет.</p>'}</section>`);}
function sources(){return shell(`<div class="page-heading"><div><h1>Источники</h1><p>Irodori, Marugoto и Tae Kim.</p></div></div><div class="sources-layout"><section class="surface progress-panel"><h2>Основа учебного модуля</h2><p>Для последовательности и проверки чтений использованы открытые материалы Irodori, Marugoto Plus и Tae Kim. Формулировки заданий, объяснения и механизм повторения подготовлены для «Каны».</p>${SOURCES.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer"><span><small>${s.organization}</small><strong>${s.title}</strong><p>${s.use}</p></span>${icon('arrow')}</a>`).join('')}<p class="tiny-note">«Кана» — самостоятельное учебное приложение. Оно не является официальным продуктом авторов этих курсов.</p></section><aside class="surface progress-panel"><span class="source-audio-icon">${icon('speaker')}</span><h2>Про озвучку</h2><p>В приложение включены готовые записи японского синтеза речи. Они воспроизводятся прямо в браузере и не требуют установки голоса.</p><p>Транскрипция на русском — приблизительная подсказка. Слушай и повторяй за записью.</p><button class="secondary" data-action="play" data-id="a">${icon('speaker')} Послушать пример</button><div class="note-divider"></div><h3>Как работает закрепление</h3><p>Знак считается закреплённым после трёх верных ответов подряд. Это ориентир для практики: уверенное чтение появится с возвращением к знакам в разные дни.</p></aside></div>`);}
function lesson(){const s=state.session;if(!s){view='home';return home();}const l=LESSONS.find(x=>x.id===s.lessonId);const title=l?l.label:s.lessonId==='mistakes'?'Повторение ошибок':'Повторение';let body='';
 if(s.phase==='learn'){const k=BY_ID[s.ids[s.learnIndex]];body=`<section class="learning-content"><span class="eyebrow">ЗНАК ${s.learnIndex+1} ИЗ ${s.ids.length}</span><h1>${title}</h1><p class="question-subtitle">Послушай звук и повтори его вслух.</p><div class="learn-card"><span class="learn-kana" lang="ja">${k.char}</span><div class="reading-label"><strong>${k.id}</strong><span>примерно «${k.ru}»</span></div><button class="audio-button" data-action="play" data-id="${k.id}">${icon('speaker')} Послушать</button><p class="pronunciation-hint">${k.hint}</p></div><div class="learn-dots">${s.ids.map((id,i)=>`<button data-action="learn-jump" data-index="${i}" class="${i===s.learnIndex?'selected':''}" aria-label="Знак ${BY_ID[id].char}">${BY_ID[id].char}</button>`).join('')}</div><p class="learning-note">Чтение латиницей пригодится в упражнениях.<br>Можно отвечать и русскими буквами.</p><button class="primary wide" data-action="learn-next">${s.learnIndex===s.ids.length-1?'К упражнениям':'Следующий знак'}${icon('arrow')}</button><button class="text-button learn-skip" data-action="learn-skip">Сразу к упражнениям</button></section>`;}
 else if(s.phase==='result'){const percent=s.firstAnswers?Math.round(s.firstCorrect/s.firstAnswers*100):0;body=`<section class="result-content"><h1>${l?'Урок завершён':'Повторение завершено'}</h1><div class="result-stats"><div><strong>${s.firstCorrect}<small> / ${s.firstAnswers}</small></strong><span>с первой попытки</span></div><div><strong>${percent}<small>%</small></strong><span>точность в занятии</span></div><div><strong>${s.bonus?'+20':stats(state).seen}</strong><span>${s.bonus?'XP за новый урок':'знаков уже знакомо'}</span></div></div>${l?`<div class="word-discovery"><span class="eyebrow">ПРИМЕР СЛОВА</span><strong lang="ja">${l.word[0]}</strong><span>${l.word[1]} · ${l.word[2]}</span><button class="icon-button" data-action="play" data-id="word-${l.id}" aria-label="Послушать слово ${l.word[2]}">${icon('speaker')}</button></div>`:''}${state.mistakes.length?`<p class="result-note">Осталось ошибок: ${state.mistakes.length}.</p>`:''}<button class="primary wide" data-action="finish">К урокам ${icon('arrow')}</button><button class="text-button" data-action="repeat-lesson" data-id="${s.lessonId}">Повторить урок</button></section>`;}
 else{const q=s.questions[s.index],k=BY_ID[q.id],f=s.feedback;const prompt=q.type==='read'?'Как читается этот знак?':q.type==='listen'?'Какой знак ты слышишь?':'Напиши чтение знака';body=`<section class="exercise-content"><div class="exercise-meta"><span class="eyebrow">${q.retry?'ПОВТОР ОШИБКИ':q.type==='listen'?'НА СЛУХ':q.type==='type'?'ВВОД ЧТЕНИЯ':'ЧТЕНИЕ'}</span><span class="muted">${s.index+1} / ${s.questions.length}</span></div><h1>${prompt}</h1><p class="question-subtitle">${q.type==='type'?'Латиницей или русскими буквами.':q.type==='listen'?'Нажми на динамик и выбери ответ.':'Выбери подходящее чтение.'}</p>${q.type==='listen'?`<button class="listening-orb" data-action="play" data-id="${q.id}" aria-label="Послушать задание">${icon('speaker')}<span>Послушать ещё</span></button>`:`<div class="exercise-kana" lang="ja">${k.char}<button class="icon-button" data-action="play" data-id="${k.id}" aria-label="Послушать знак">${icon('speaker')}</button></div>`}${q.type==='type'?`<form id="answer-form"><label class="sr-only" for="reading">Чтение знака</label><input id="reading" name="reading" class="reading-input ${f?(f.correct?'input-correct':'input-wrong'):''}" placeholder="Твой ответ" autocomplete="off" autocapitalize="none" spellcheck="false" ${f?'disabled':''} value="${f?esc(f.value):''}"><button class="primary wide" type="submit" ${f?'disabled':''}>Проверить ${icon('check')}</button></form>`:`<div class="answer-grid">${q.options.map((id,i)=>`<button class="answer-option ${f?(id===q.id?'answer-correct':id===f.value?'answer-wrong':'answer-muted'):''}" data-action="answer" data-id="${id}" ${f?'disabled':''}><span class="option-key">${i+1}</span><span class="${q.type==='listen'?'option-kana':''}" ${q.type==='listen'?'lang="ja"':''}>${q.type==='listen'?BY_ID[id].char:id}</span>${f&&id===q.id?icon('check'):f&&id===f.value?icon('close'):''}</button>`).join('')}</div>`}<div class="exercise-feedback ${f?(f.correct?'is-correct':'is-wrong'):''}" ${f?'role="status" aria-live="polite"':''}>${f?`<div class="feedback-main"><span class="feedback-icon">${icon(f.correct?'check':'repeat')}</span><div><strong>${f.correct?'Верно':'Ошибка'}</strong><p>${f.correct?`${k.char} читается ${k.id}${f.earned?` · +${f.earned} XP`:''}`:`${k.char} → ${k.id} · примерно «${k.ru}». Повторится в этом уроке.`}</p></div></div>${!f.correct?`<p class="feedback-hint">${k.hint}</p>`:''}<button class="primary wide" data-action="next">Продолжить ${icon('arrow')}</button>`:''}</div></section>`;}
 const fraction=s.phase==='learn'?(s.learnIndex/s.ids.length)*10:s.phase==='result'?100:10+(s.index/s.questions.length)*90;
 return `<div class="lesson-shell"><header class="lesson-top"><button class="exit-button" data-action="exit" aria-label="Выйти из занятия, сохранив прогресс">${icon('close')}</button><div class="lesson-top-center"><span>${title}</span><div class="session-track" role="progressbar" aria-label="Ход занятия" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(fraction)}"><span style="width:${fraction}%"></span></div></div><span class="session-xp">${icon('star')}${state.xp}</span></header><main id="main" tabindex="-1" class="lesson-main">${body}</main></div>`;}
const cloudLabels={disconnected:'Не подключено','auth-required':'Нужен вход',connecting:'Вход Google',syncing:'Синхронизация',synced:'Сохранено',pending:'Есть изменения',offline:'Нет соединения',error:'Ошибка',conflict:'Конфликт версий'};
function cloudIndicator(){const c=cloud?.snapshot();return `<button id="cloud-indicator" class="cloud-indicator ${c?.status||'disconnected'}" data-action="cloud-open" aria-label="Google Sheets: ${cloudLabels[c?.status]||'Не подключено'}" title="Google Sheets: ${cloudLabels[c?.status]||'Не подключено'}">${icon('cloud')}<i></i></button>`;}
function cloudWidget(){const c=cloud.snapshot(),busy=['syncing','connecting'].includes(c.status);const descriptions={disconnected:'Войди в Google для сохранения прогресса между устройствами.','auth-required':'Сеанс Google истёк. Локальные изменения сохраняются.',connecting:'Заверши вход в окне Google.',syncing:'Проверка и сохранение прогресса.',synced:'Прогресс сохранён в личной таблице.',pending:'Изменения сохранятся автоматически через несколько секунд.',offline:'Прогресс сохранён локально. Синхронизация продолжится после подключения.',error:c.error||'Синхронизация не выполнена.',conflict:'На устройствах есть разные версии. Выбери, какую продолжить.'};return `<section class="surface progress-panel cloud-panel" data-cloud-panel><div class="cloud-panel-heading"><h2>Google Sheets</h2><span class="sync-status ${c.status}">${cloudLabels[c.status]}</span></div><p>${c.configured?esc(descriptions[c.status]||''): 'Сначала укажи Google Client ID. Нужна однократная настройка Google Cloud.'}</p><div class="cloud-controls">${!c.configured?`<button class="primary" data-action="cloud-config">Настроить</button>`:c.status==='conflict'?`<button class="primary" data-action="cloud-conflict">Выбрать версию</button>`:c.connected?`<button class="primary" data-action="cloud-sync" ${busy?'disabled':''}>${icon('repeat')} Синхронизировать</button>`:`<button class="primary" data-action="cloud-connect" ${busy?'disabled':''}>Подключить Google</button>`}${c.connected?'<button class="text-button" data-action="cloud-disconnect">Отключить</button>':''}${c.configured?'<button class="text-button" data-action="cloud-config">Настройка</button>':''}</div>${c.sheetUrl&&/^https:\/\/docs\.google\.com\//.test(c.sheetUrl)?`<a class="sheet-link" href="${esc(c.sheetUrl)}" target="_blank" rel="noopener noreferrer">Открыть таблицу ${icon('arrow')}</a>`:''}${c.lastSavedAt?`<p class="tiny-note">Последняя запись: ${new Date(c.lastSavedAt).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</p>`:''}</section>`;}
function refreshCloudUI(){if(!cloud)return;const panel=document.querySelector('[data-cloud-panel]');if(panel)panel.outerHTML=cloudWidget();const indicator=document.querySelector('#cloud-indicator');if(indicator)indicator.outerHTML=cloudIndicator();}
function cloudPage(){return shell(`<div class="page-heading"><div><h1>Синхронизация</h1><p>Сохранение прогресса между устройствами.</p></div></div>${cloudWidget()}<section class="surface progress-panel"><h2>Как это работает</h2><p>Приложение создаёт таблицу «Кана — прогресс» в твоём Google Drive. Устройства находят её после входа в один и тот же аккаунт.</p><p>Ответы сначала сохраняются в браузере. Пока подключён Google, изменения отправляются в таблицу автоматически. Если версии разошлись, приложение предложит выбрать сохранение.</p><p>Доступ ограничен файлами, созданными или открытыми этим приложением. Токен входа хранится в памяти до закрытия страницы или истечения сеанса.</p><div class="cloud-help"><a href="google-setup.html" target="_blank" rel="noopener noreferrer">Инструкция настройки</a><a href="privacy.html" target="_blank" rel="noopener noreferrer">Данные и доступ</a></div></section>`);}
function cloudConfig(){const dialog=document.querySelector('#dialog'),c=cloud.snapshot();dialog.innerHTML=`<div class="dialog-inner cloud-config"><button class="dialog-close icon-button" id="dialog-cancel" aria-label="Закрыть">${icon('close')}</button><h2>Подключение Google</h2><p>Нужен OAuth Client ID для веб-приложения. Это публичный идентификатор; Client Secret не требуется.</p><form id="google-config"><label for="google-client-id">Google Client ID</label><input id="google-client-id" class="reading-input" name="clientId" type="text" autocomplete="off" placeholder="123-abc.apps.googleusercontent.com" value="${esc(c.clientId)}" required><button type="submit" class="primary wide">Сохранить</button></form><a class="setup-link" href="google-setup.html" target="_blank" rel="noopener noreferrer">Как создать Client ID</a></div>`;dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();}
function cloudConflict(){const c=cloud.snapshot();if(!c.conflict)return;const dialog=document.querySelector('#dialog');const card=(id,label,st,date)=>`<button class="conflict-choice" data-action="cloud-choose" data-id="${esc(id)}"><strong>${esc(label)}</strong><span>${st.completed.length}/10 уроков · ${st.xp} XP · ${st.answered} ответов</span>${date?`<small>${new Date(date).toLocaleString('ru-RU')}</small>`:''}</button>`;dialog.innerHTML=`<div class="dialog-inner"><h2>Какой прогресс продолжить?</h2><p>Выбранная версия станет текущей на всех устройствах. Старые записи останутся в таблице.</p>${card('local','Это устройство',state)}${c.conflict.heads.map((h,i)=>card(h.id,`Google Sheets${c.conflict.heads.length>1?' · версия '+(i+1):''}`,h.state,h.savedAt)).join('')}<button class="text-button" id="dialog-cancel">Отмена</button></div>`;dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();}
function render(){app.innerHTML=view==='lesson'?lesson():view==='alphabet'?alphabet():view==='progress'?progress():view==='sources'?sources():view==='sync'?cloudPage():home();updateSoundButtons();refreshCloudUI();}
function navigate(target){view=target;render();window.scrollTo({top:0,behavior:'instant'});}
function begin(id){if(state.session&&!state.session.finished){if(state.session.lessonId===id){navigate('lesson');return;}showDialog('Продолжить новое занятие?','Прогресс ответов сохранён. Незаконченный урок будет заменён новым.',()=>doBegin(id),'Начать новое');return;}doBegin(id);}
function doBegin(id){const s=startSession(id,state);if(!s){toast('Нет знаков для повторения.');return;}state={...state,session:s};save();navigate('lesson');}
function updateSoundButtons(){document.querySelectorAll('[data-action="play"]').forEach(b=>b.classList.toggle('playing',b.dataset.id===playingId));}
async function play(id){if(!id||!/^[a-z-]+$/.test(id))return;if(audio){audio.pause();audio.currentTime=0;}audio=new Audio(`assets/audio/${id}.mp3`);playingId=id;updateSoundButtons();audio.onended=()=>{playingId=null;updateSoundButtons();};try{await audio.play();}catch(error){playingId=null;updateSoundButtons();toast('Не получилось включить запись. Проверь соединение и нажми ещё раз.',true);}}
function showDialog(title,text,confirm,label='Продолжить'){const dialog=document.querySelector('#dialog');dialog.innerHTML=`<div class="dialog-inner"><span class="dialog-icon">${icon('info')}</span><h2>${esc(title)}</h2><p>${esc(text)}</p><button class="primary wide" id="dialog-confirm">${label}</button><button class="text-button" id="dialog-cancel">Отмена</button></div>`;dialog.querySelector('#dialog-confirm').onclick=()=>{dialog.close();confirm();};dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.showModal();}
function kanaModal(id){const k=BY_ID[id],dialog=document.querySelector('#dialog');dialog.innerHTML=`<div class="dialog-inner kana-dialog"><button class="dialog-close icon-button" id="dialog-cancel" aria-label="Закрыть">${icon('close')}</button><span class="learn-kana" lang="ja">${k.char}</span><div class="reading-label"><strong>${k.id}</strong><span>примерно «${k.ru}»</span></div><p>${k.hint}</p><button class="audio-button" id="kana-play">${icon('speaker')} Послушать ещё</button></div>`;dialog.querySelector('#dialog-cancel').onclick=()=>dialog.close();dialog.querySelector('#kana-play').onclick=()=>play(id);dialog.showModal();play(id);}
function submitAnswer(value){if(!value.trim())return;state=answer(state,value);save();render();if(state.session?.feedback){document.querySelector('.exercise-feedback').scrollIntoView({block:'nearest',behavior:'smooth'});document.querySelector('[data-action="next"]')?.focus({preventScroll:true});}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;
 switch(action){case 'nav':navigate(b.dataset.view);break;case 'cloud-open':navigate('sync');break;case 'cloud-config':cloudConfig();break;case 'cloud-connect':if(!cloud.snapshot().configured){cloudConfig();break;}cloud.connect().catch(e=>toast(e.message,true));break;case 'cloud-sync':cloud.sync();break;case 'cloud-disconnect':cloud.disconnect();break;case 'cloud-conflict':cloudConflict();break;case 'cloud-choose':document.querySelector('#dialog').close();cloud.resolveConflict(id).catch(e=>toast(e.message,true));break;case 'start':begin(id);break;case 'resume':navigate('lesson');break;case 'play':play(id);break;case 'kana':kanaModal(id);break;case 'learn-jump':state.session.learnIndex=Number(b.dataset.index);save();render();break;case 'learn-skip':state.session.phase='exercise';save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'learn-next':if(state.session.learnIndex<state.session.ids.length-1)state.session.learnIndex++;else state.session.phase='exercise';save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'answer':submitAnswer(id);break;case 'next':state=advance(state);save();render();window.scrollTo({top:0,behavior:'instant'});break;case 'exit':navigate('home');toast('Занятие сохранено.');break;case 'finish':state.session=null;save();navigate('home');break;case 'repeat-lesson':state.session=null;doBegin(id);break;case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`kana-garden-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Файл прогресса подготовлен.');break;}case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(!input.files[0])return;if(input.files[0].size>2e6)throw new Error('Файл слишком большой.');const imported=validateState(JSON.parse(await input.files[0].text()));showDialog('Восстановить прогресс из файла?','Текущее сохранение в этом браузере будет заменено данными из файла.',()=>{state=imported;save();navigate('progress');toast('Прогресс восстановлен.');},'Восстановить');}catch(error){toast(error.message||'Не удалось прочитать файл.',true);}};input.click();break;}case 'reset':showDialog('Сбросить прогресс?','Опыт, история и результаты в этом браузере будут удалены. Перед этим можно выгрузить файл прогресса.',()=>{state=freshState();save();navigate('home');toast('Прогресс сброшен.');},'Начать заново');break;}
});
document.addEventListener('submit',async event=>{if(event.target.id==='google-config'){event.preventDefault();const button=event.target.querySelector('button[type=submit]');button.disabled=true;try{await cloud.configure(String(new FormData(event.target).get('clientId')||'').trim());document.querySelector('#dialog').close();toast('Client ID сохранён. Нажми «Подключить».');}catch(e){button.disabled=false;toast(e.message,true);}return;}if(event.target.id!=='answer-form')return;event.preventDefault();submitAnswer(new FormData(event.target).get('reading')||'');});
document.addEventListener('keydown',event=>{if(view!=='lesson'||document.querySelector('#dialog').open||event.repeat)return;const tag=event.target.tagName;if(['INPUT','TEXTAREA'].includes(tag))return;const s=state.session;if(s?.phase!=='exercise')return;if(event.key==='Enter'&&s.feedback){event.preventDefault();document.querySelector('[data-action="next"]')?.click();}else if(/^[1-4]$/.test(event.key)&&!s.feedback){const q=s.questions[s.index];if(q.type!=='type'){event.preventDefault();submitAnswer(q.options[Number(event.key)-1]);}}});
window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY||!event.newValue)return;try{state=validateState(JSON.parse(event.newValue));render();toast('Прогресс обновлён из другой вкладки.');}catch(error){}});
cloud=createGoogleSync({getState:()=>state,applyState:remote=>{state=validateState(JSON.parse(JSON.stringify(remote)));save(false);navigate('home');},onStatus:refreshCloudUI,onMessage:toast});
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
